"""Write a Markdown inventory of the Win16 APIs a binary imports, from its analysis JSON.

    .venv/Scripts/python tools/import_report.py build/PLAY_E.analysis.json docs/imports.md
"""
import json
import sys
from collections import defaultdict


def main(analysis_path, out_path):
    analysis = json.load(open(analysis_path))
    by_module = defaultdict(list)
    for imp in analysis["imports"]:
        by_module[imp["module"]].append(imp)

    lines = [
        "# Win16 imports used by PLAY_E.EXE",
        "",
        "Generated by `tools/import_report.py` from the IDA analysis export. "
        "`refs` counts call/reference sites in the program (OPTLOADER stub excluded).",
        "",
        "| Module | Imports | Reference sites |",
        "|---|---:|---:|",
    ]
    order = sorted(by_module, key=lambda m: -sum(i["refs"] for i in by_module[m]))
    for module in order:
        imps = by_module[module]
        lines.append(f"| {module} | {len(imps)} | {sum(i['refs'] for i in imps)} |")
    for module in order:
        lines += ["", f"## {module}", "", "| Ordinal | Name | refs |", "|---:|---|---:|"]
        for imp in sorted(by_module[module], key=lambda i: (-i["refs"], i["ordinal"])):
            lines.append(f"| {imp['ordinal']} | {imp['name']} | {imp['refs']} |")
    open(out_path, "w", newline="\n").write("\n".join(lines) + "\n")
    print(f"wrote {out_path}")


if __name__ == "__main__":
    main(*sys.argv[1:3])
